function ord_ctyList(){return Array.from(new Set(orgCountries().concat(plCountries())));}
function ord_ctyCard(){const ed=can('ota.countries')||can('ota.settings');const ccs=ord_ctyList();
 const blk=cc=>{const c=otaCountry(cc);const id=k=>'cy_'+cc+'_'+k;const lk=ccyLocked(cc);
  return `<fieldset class="stack ord_cty" style="border:0;padding:0;margin:0"><legend class="row g8"><b>${esc(ctyName(cc))}</b> <span class="mono xs faint">${cc}</span> ${ui.badge(c.currency,'accent')}</legend>
   <div class="grid2">${ui.field({id:id('ccy'),label:t('ord.cy.ccy')+' <span class="mono xs faint">currency</span>',type:'select',value:c.currency,options:CCY_LIST.map(x=>[x,x]),hint:lk?t('ord.cy.ccyLocked'):t('ord.cy.ccyH'),attrs:ed&&!lk?'':'disabled'})}${lk?`<input type="hidden" name="${id('ccy')}" value="${esc(c.currency)}">`:''}${ui.field({id:id('oss'),label:t('ord.cy.oss')+' <span class="mono xs faint">oss_no</span>',value:c.oss_no,mono:true,hint:t('ord.cy.ossH'),attrs:ed?'maxlength="20" autocomplete="off"':'readonly'})}</div>
   <div class="grid2">${ui.field({id:id('vat'),label:t('ord.cy.vat')+' <span class="mono xs faint">OTA_VAT_LOCAL</span>',value:c.vat_local,hint:t('ord.cy.vatH'),attrs:ed?'maxlength="120"':'readonly'})}${ui.field({id:id('delay'),label:t('ord.cy.delay'),type:'number',value:c.delay_hours,hint:t('ord.cy.delayH'),attrs:'min="1" max="24" step="1" inputmode="numeric" '+(ed?'':'readonly')})}</div>
   ${ui.field({id:id('rep'),label:t('ord.cy.rep')+' <span class="mono xs faint">OTA_REP_LOCAL</span>',type:'textarea',rows:2,value:c.rep_local,hint:t('ord.cy.repH'),attrs:ed?'maxlength="300"':'readonly'})}
   <label class="chk small"><input type="checkbox" name="${id('own')}" ${c.ownership_v10_enabled?'checked':''} ${ed?'':'disabled'}><span><b>${t('ord.cy.own')}</b> <span class="mono xs faint">ownership_v10_enabled</span><br><span class="faint xs">${t('ord.cy.ownH')}</span></span></label></fieldset>`;};
 return `<section class="card"><form data-form="ord_cty" novalidate><div class="hd"><h2 class="row g8">${icon('globe','sm')}${t('ord.cy.title')}</h2>${ui.badge('OTA','violet')}</div>
  <div class="bd stack">${ui.note('admin',t('ord.cy.note'))}${ccs.map(blk).join('<hr class="sep">')}</div><div class="ft">${ui.btn(t('c.save'),{kind:'primary',type:'submit',icon:'check',disabled:!ed})}</div></form></section>`;}
FORM.ord_cty=f=>{if(!(can('ota.countries')||can('ota.settings')))return;clearErrs(f);const d=formData(f);const ch=[];let bad=false;
 ord_ctyList().forEach(cc=>{const id=k=>'cy_'+cc+'_'+k;const before=JSON.stringify(otaCountry(cc));
  const e=otaCountrySet(cc,{vat_local:d[id('vat')],rep_local:d[id('rep')],delay_hours:d[id('delay')],ownership_v10_enabled:!!d[id('own')],currency:d[id('ccy')]||otaCountry(cc).currency,oss_no:d[id('oss')]||''});
  if(e==='delay'){setErr(f,id('delay'),t('ord.cy.delayE'));bad=true;return;}if(e==='currency'){setErr(f,id('ccy'),t('ord.cy.ccyLocked'));bad=true;return;}if(e==='oss'){setErr(f,id('oss'),t('ord.cy.ossE'));bad=true;return;}if(JSON.stringify(otaCountry(cc))!==before)ch.push(cc);});
 if(bad){const el=f.querySelector('[aria-invalid="true"]');if(el)el.focus();return;}
 if(!ch.length){toast(t('ord.req.nochange'));return;}ch.forEach(cc=>audit('ota.countries.update',cc,otaCountry(cc)));const m=t('ord.cy.saved',{c:ch.map(ctyName).join(', ')});log(m);toast(m);rerender();};
/* sub-processor directory (Document 06 Annex 1, ТЗ v10 2.9) */
function ord_spCard(){const ed=can('ota.settings');const d=subprocDir();const rows=subprocRows();const L=S.lang==='en'?'en':'ru';
 const tbl=ui.table([{label:t('ord.sp.name')},{label:t('ord.sp.service')},{label:t('ord.sp.loc')}],rows.map(r=>({cells:[`<b class="small">${esc(r.name.en)}</b>${r.name.ru&&r.name.ru!==r.name.en?`<br><span class="xs faint">${esc(r.name.ru)}</span>`:''}`,`<span class="small">${esc(r.service.en)}</span><br><span class="xs faint">${esc(r.service.ru)}</span>`,`<span class="small">${esc(r.location.en)}</span>${r.location.ru&&r.location.ru!==r.location.en?` <span class="xs faint">/ ${esc(r.location.ru)}</span>`:''}`]})));
 const em=d.rows.find(r=>r.id==='email');const miss=!d.awsMerged&&em&&!String(em.name.en||'').trim();
 const ns=(S.notices||[]).filter(n=>n.type==='subproc');
 const hist=ns.length?`<div class="stack"><b class="small">${t('ord.sp.notices')}</b>${ns.slice(0,5).map(n=>`<div class="row between wrap g8 small"><span>${fmtDate(n.createdAt)} · ${esc([n.added.length?t('ord.sp.added',{n:n.added.join(', ')}):'',n.removed.length?t('ord.sp.removed',{n:n.removed.join(', ')}):'',n.changed.length?t('ord.sp.changed',{n:n.changed.join(', ')}):''].filter(Boolean).join(' · '))}</span><span class="xs faint">${t('ord.sp.eff',{d:fmtDate(n.effective)})}</span></div>`).join('')}</div>`:'';
 return `<section class="card"><div class="hd"><h2 class="row g8">${icon('users','sm')}${t('ord.sp.title')}</h2><div class="row g8">${ui.badge('OTA','violet')}${ui.btn(t('c.edit'),{size:'sm',icon:'edit',act:'ord_spEdit',disabled:!ed})}</div></div>
  <div class="bd stack">${ui.note('admin',t('ord.sp.note'))}${miss?ui.note('warn',t('ord.sp.emailMiss')):''}<div class="tblwrap" style="margin:0">${tbl}</div>${hist}</div></section>`;}
ACT.ord_spEdit=()=>{if(!can('ota.settings'))return;const d=subprocDir();
 const inp=(n,v,l)=>`<input class="inp" name="${n}" value="${esc(v||'')}" aria-label="${esc(l)}" maxlength="160">`;
 const row=(r,i)=>`<fieldset class="ord_sprow" style="border:1px solid var(--line);border-radius:10px;padding:10px;margin:0"><legend class="xs faint">${r.id==='email'?t('ord.sp.emailRow'):'#'+(i+1)}</legend><input type="hidden" name="sp_${i}_id" value="${esc(r.id)}">
  <div class="grid3">${inp('sp_'+i+'_ne',r.name.en,t('ord.sp.name')+' EN')}${inp('sp_'+i+'_se',r.service.en,t('ord.sp.service')+' EN')}${inp('sp_'+i+'_le',r.location.en,t('ord.sp.loc')+' EN')}</div>
  <div class="grid3" style="margin-top:6px">${inp('sp_'+i+'_nr',r.name.ru,t('ord.sp.name')+' RU')}${inp('sp_'+i+'_sr',r.service.ru,t('ord.sp.service')+' RU')}${inp('sp_'+i+'_lr',r.location.ru,t('ord.sp.loc')+' RU')}</div>
  ${r.id!=='email'?`<label class="chk xs" style="margin-top:6px"><input type="checkbox" name="sp_${i}_del"><span>${t('ord.sp.del')}</span></label>`:''}</fieldset>`;
 const rows=d.rows.concat([{id:'new',name:{en:'',ru:''},service:{en:'',ru:''},location:{en:'',ru:''}}]);
 modal(t('ord.sp.editT'),`<form id="ord_spF" data-form="ord_sp" class="stack" novalidate><input type="hidden" name="sp_n" value="${rows.length}">${ui.note('info',t('ord.sp.editP',{n:SUBPROC_NOTICE_DAYS}))}
  <p class="xs faint">${t('ord.sp.cols')}</p>${rows.map(row).join('')}
  <label class="chk small"><input type="checkbox" name="sp_aws" ${d.awsMerged?'checked':''}><span><b>${t('ord.sp.aws')}</b><br><span class="faint xs">Amazon Web Services — Hosting, storage, backups, transactional email — {region}</span></span></label>
  <div class="grid2">${ui.field({id:'sp_reg_en',label:t('ord.sp.region')+' EN',value:d.awsRegion.en})}${ui.field({id:'sp_reg_ru',label:t('ord.sp.region')+' RU',value:d.awsRegion.ru})}</div>
  ${ui.field({id:'sp_note',label:t('ord.sp.why'),hint:t('c.optional'),attrs:'maxlength="200"'})}</form>`,
  ui.btn(t('c.cancel'),{act:'ovclose'})+`<button class="btn primary" type="submit" form="ord_spF">${icon('send','sm')}<span>${t('ord.sp.save')}</span></button>`,{wide:true});};
FORM.ord_sp=f=>{if(!can('ota.settings'))return;const d=formData(f);const n=+d.sp_n||0;const rows=[];const g=(i,k)=>String(d['sp_'+i+'_'+k]||'').trim();
 for(let i=0;i<n;i++){const id=g(i,'id');if(d['sp_'+i+'_del'])continue;const r={id:id==='new'?uid('sp'):id,name:{en:g(i,'ne'),ru:g(i,'nr')||g(i,'ne')},service:{en:g(i,'se'),ru:g(i,'sr')||g(i,'se')},location:{en:g(i,'le'),ru:g(i,'lr')||g(i,'le')}};
  if(id==='new'&&!r.name.en)continue;if(id!=='email'&&(!r.name.en||!r.service.en)){toast(t('ord.sp.e'),'bad');return;}rows.push(r);}
 const nt=subprocUpdate({rows,awsMerged:!!d.sp_aws,awsRegion:{en:String(d.sp_reg_en||'').trim()||'UAE',ru:String(d.sp_reg_ru||'').trim()||'ОАЭ'}},String(d.sp_note||'').trim());
 closeOverlay();if(nt){const m=t('ord.sp.sent',{d:fmtDate(nt.effective)});log(m);toast(m);}else toast(t('ord.sp.noChange'));rerender();};
FORM.ord_req=f=>{if(!can('ota.settings'))return;const d=formData(f);const changed=[];
 Object.keys(d).forEach(n=>{if(!n.startsWith('rq_'))return;const k=n.slice(3);const v=String(d[n]||'').trim();if(((S.ota||{})[k]||'')!==v){changed.push(k);S.ota[k]=v;}});
 if(!changed.length){toast(t('ord.req.nochange'));return;}audit('ota.data.update',changed.join(','),{keys:changed});log(t('ord.req.logSaved'));toast(t('ord.req.saved',{n:changed.length}));rerender();};
ACT.ord_reqReset=()=>{if(!can('ota.settings'))return;S.ota=Object.assign({},S.ota,otaSeed());audit('ota.data.reset','',{});log(t('ord.req.logReset'));toast(t('ord.req.resetDone'));rerender();};

